// Shapes of the static data generated by scripts/build_site_data.py.

export interface Ratio {
  numerator: number;
  denominator: number;
  rate: number | null;
}

export interface MethodSummary {
  id: string;
  label: string;
  runs: number;
  invalid_runs: number;
  invalid_run_ids: string[];
  seeded_detection: Ratio;
  seeded_cases_detected_at_least_once: Ratio;
  false_alarms_on_clean: Ratio;
  per_case_detection: Record<string, Ratio>;
  median_operations_to_first_difference: number | null;
  median_time_to_first_difference_seconds: number | null;
  time_to_first_difference_range_seconds: [number, number] | null;
  total_operations_executed: number;
  total_search_operations: number;
  median_sequence_length_before_shrink: number | null;
  median_sequence_length_after_shrink: number | null;
  replay_success: Ratio;
  total_runtime_seconds: number;
  inconclusive_runs: number;
}

export interface BenchCase {
  name: string;
  defect: string | null;
  seeded: boolean;
  description: string;
}

export interface RunRecord {
  case: string;
  defect: string | null;
  seeded: boolean;
  method: string;
  seed: number | null;
  outcome: string;
  detected: boolean;
  search_operations: number | null;
  operations_executed: number | null;
  operations_to_first_difference: number | null;
  time_to_first_difference_seconds: number | null;
  sequence_length_before_shrink: number | null;
  sequence_length_after_shrink: number | null;
  verification_reproduced: number | null;
  verification_checks: number | null;
  runtime_seconds: number | null;
}

export interface BenchmarkData {
  generated_from: Record<string, string>;
  meta: {
    careo_version: string;
    source_commit: string;
    finished_at: string;
    seeds: number;
    budget_operations: number;
    max_steps: number;
    replay_checks: number;
    python: string;
    platform: string;
  };
  cases: BenchCase[];
  methods: MethodSummary[];
  records: RunRecord[];
  reproduce: string;
}

export interface Difference {
  path: string;
  kind: string;
  reference?: unknown;
  candidate?: unknown;
  detail?: string;
}

export interface Observation {
  status: string;
  code?: number;
  headers?: Record<string, string>;
  body?: unknown;
  body_text?: string;
  error?: string;
  compared_body?: unknown;
  duration_seconds: number;
}

export type Rows = Record<string, Record<string, unknown>[]>;

export interface Step {
  op: string;
  params?: Record<string, unknown>;
  query?: Record<string, unknown>;
  body?: unknown;
}

export interface Evidence {
  index: number;
  step: Step;
  verdict: string;
  differences: Difference[];
  notes: string[];
  produced: string | null;
  reference: Observation;
  candidate: Observation;
  state?: { reference: Rows; candidate: Rows };
}

export interface DemoData {
  generated_from: { report: string; report_sha256: string; precomputed: boolean; note: string };
  careo_version: string;
  outcome: string;
  summary: string;
  isolation: Record<string, boolean>;
  warnings: string[];
  generation: Record<string, unknown>;
  stats: Record<string, number | boolean | null>;
  original_sequence: { length: number; steps: Step[] };
  minimized_sequence: { length: number; steps: Step[]; method: string; claim: string };
  verification: { checks: number; reproduced: number };
  evidence: Evidence[];
  id_mapping: { reference: Record<string, unknown>; candidate: Record<string, unknown> };
  regression_json: unknown;
  regression_test: string;
  spec: string;
  sources: Record<"reference" | "candidate", { file: string; function: string }>;
  seeded_bug: string;
}
